/**
 * Kiosk data model.
 *
 * Conventions
 * - Money is integer pesewas (`*_pesewas`). No floats, no numeric->string casts.
 * - Orders snapshot names and prices so later edits never rewrite history.
 * - Timestamps are timestamptz; ids are uuid v4 generated by Postgres.
 * - Every status change on an order is appended to order_events.
 */
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const id = () => uuid("id").primaryKey().default(sql`gen_random_uuid()`);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const money = (name: string) => integer(name);

/* ───────────────────────── Enums ───────────────────────── */

export const accountRole = pgEnum("account_role", ["seller", "admin"]);
export const sellerStatus = pgEnum("seller_status", ["pending", "approved", "suspended", "banned"]);
export const sellerPlan = pgEnum("seller_plan", ["trial", "starter", "pro"]);
export const productStatus = pgEnum("product_status", ["draft", "active", "archived"]);
export const orderChannel = pgEnum("order_channel", ["storefront", "whatsapp"]);
export const orderStatus = pgEnum("order_status", [
  "pending_payment",
  "paid",
  "preparing",
  "out_for_delivery",
  "delivered",
  "completed",
  "cancelled",
  "refunded",
]);
export const fulfilment = pgEnum("fulfilment", ["delivery", "pickup"]);
export const conversationMode = pgEnum("conversation_mode", ["bot", "human", "closed"]);
export const messageDirection = pgEnum("message_direction", ["inbound", "outbound"]);
export const messageSender = pgEnum("message_sender", ["customer", "bot", "seller", "admin", "system"]);
export const complaintStatus = pgEnum("complaint_status", [
  "open",
  "investigating",
  "resolved_refund",
  "resolved_payout",
  "dismissed",
]);
export const otpPurpose = pgEnum("otp_purpose", ["login"]);

/* ───────────────────────── Identity ───────────────────────── */

/** Anyone who signs in to a dashboard. Customers never have accounts. */
export const accounts = pgTable("accounts", {
  id: id(),
  phone: text("phone").notNull().unique(),
  role: accountRole("role").notNull().default("seller"),
  lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
  createdAt: createdAt(),
});

export const otpChallenges = pgTable(
  "otp_challenges",
  {
    id: id(),
    phone: text("phone").notNull(),
    purpose: otpPurpose("purpose").notNull().default("login"),
    codeHash: text("code_hash").notNull(),
    attempts: smallint("attempts").notNull().default(0),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    consumedAt: timestamp("consumed_at", { withTimezone: true }),
    ip: text("ip"),
    createdAt: createdAt(),
  },
  (t) => [index("otp_phone_created_idx").on(t.phone, t.createdAt)],
);

/** Opaque session tokens; only the SHA-256 of the token is stored. */
export const sessions = pgTable(
  "sessions",
  {
    tokenHash: text("token_hash").primaryKey(),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    userAgent: text("user_agent"),
    ip: text("ip"),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_account_idx").on(t.accountId)],
);

/* ───────────────────────── Sellers ───────────────────────── */

export type StoreTheme = {
  preset: string;
  accent?: string;
  radius?: number;
  layout?: "grid" | "feed";
};

export const sellers = pgTable(
  "sellers",
  {
    id: id(),
    accountId: uuid("account_id")
      .notNull()
      .unique()
      .references(() => accounts.id, { onDelete: "restrict" }),
    ownerName: text("owner_name").notNull(),
    storeName: text("store_name").notNull(),
    slug: text("slug").notNull(),
    bio: text("bio"),
    instagramUrl: text("instagram_url"),
    tiktokUrl: text("tiktok_url"),
    /** WhatsApp number that receives order notifications. Defaults to the login phone. */
    notifyPhone: text("notify_phone").notNull(),
    status: sellerStatus("status").notNull().default("pending"),
    plan: sellerPlan("plan").notNull().default("trial"),
    theme: jsonb("theme").$type<StoreTheme>().notNull().default({ preset: "chalk" }),
    pickupEnabled: boolean("pickup_enabled").notNull().default(false),
    pickupAddress: text("pickup_address"),
    freeDeliveryOverPesewas: money("free_delivery_over_pesewas"),
    /** Monthly cap on bot replies, protects the shared WhatsApp bill. */
    botMessageQuota: integer("bot_message_quota").notNull().default(1500),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    approvedBy: uuid("approved_by").references(() => accounts.id),
    suspendedReason: text("suspended_reason"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("sellers_slug_lower_uq").on(sql`lower(${t.slug})`),
    index("sellers_status_idx").on(t.status),
  ],
);

export const deliveryZones = pgTable(
  "delivery_zones",
  {
    id: id(),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    feePesewas: money("fee_pesewas").notNull(),
    etaLabel: text("eta_label"),
    active: boolean("active").notNull().default(true),
    position: smallint("position").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("zones_seller_name_uq").on(t.sellerId, sql`lower(${t.name})`),
    check("zones_fee_nonneg", sql`${t.feePesewas} >= 0`),
  ],
);

/* ───────────────────────── Catalogue ───────────────────────── */

export const products = pgTable(
  "products",
  {
    id: id(),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    description: text("description"),
    category: text("category"),
    status: productStatus("status").notNull().default("draft"),
    pricePesewas: money("price_pesewas").notNull(),
    compareAtPesewas: money("compare_at_pesewas"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("products_seller_status_idx").on(t.sellerId, t.status),
    check("products_price_pos", sql`${t.pricePesewas} > 0`),
  ],
);

/**
 * Uploaded before the product is saved, so an image belongs to a seller first
 * and is attached to a product on save. Unattached images older than a day are
 * garbage. `storageKey` is a folder holding one WebP per IMAGE_WIDTHS entry.
 */
export const productImages = pgTable(
  "product_images",
  {
    id: id(),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "cascade" }),
    productId: uuid("product_id").references(() => products.id, { onDelete: "cascade" }),
    storageKey: text("storage_key").notNull(),
    width: integer("width").notNull(),
    height: integer("height").notNull(),
    /** Base64 ThumbHash for instant blurred placeholders. */
    thumbhash: text("thumbhash"),
    position: smallint("position").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index("images_product_idx").on(t.productId, t.position),
    index("images_seller_unattached_idx").on(t.sellerId, t.createdAt).where(sql`${t.productId} IS NULL`),
  ],
);

export const productVariants = pgTable(
  "product_variants",
  {
    id: id(),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "cascade" }),
    size: text("size"),
    color: text("color"),
    sku: text("sku"),
    /** Null means "use the product price". */
    pricePesewas: money("price_pesewas"),
    stock: integer("stock").notNull().default(0),
    position: smallint("position").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index("variants_product_idx").on(t.productId, t.position),
    uniqueIndex("variants_product_size_color_uq").on(
      t.productId,
      sql`coalesce(lower(${t.size}), '')`,
      sql`coalesce(lower(${t.color}), '')`,
    ),
    check("variants_stock_nonneg", sql`${t.stock} >= 0`),
  ],
);

/* ───────────────────────── Customers & orders ───────────────────────── */

/** WhatsApp/storefront buyers, keyed by phone. No login. */
export const customers = pgTable("customers", {
  id: id(),
  phone: text("phone").notNull().unique(),
  name: text("name"),
  /** Which store's assistant this customer is currently talking to on the shared number. */
  activeSellerId: uuid("active_seller_id").references(() => sellers.id, { onDelete: "set null" }),
  createdAt: createdAt(),
});

export const orders = pgTable(
  "orders",
  {
    id: id(),
    /** Short human-facing reference, e.g. K7F3Q2. */
    code: text("code").notNull().unique(),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "restrict" }),
    customerId: uuid("customer_id")
      .notNull()
      .references(() => customers.id, { onDelete: "restrict" }),
    channel: orderChannel("channel").notNull(),
    status: orderStatus("status").notNull().default("pending_payment"),
    fulfilment: fulfilment("fulfilment").notNull().default("delivery"),

    subtotalPesewas: money("subtotal_pesewas").notNull(),
    deliveryFeePesewas: money("delivery_fee_pesewas").notNull().default(0),
    totalPesewas: money("total_pesewas").notNull(),
    platformFeePesewas: money("platform_fee_pesewas").notNull().default(0),

    deliveryZoneId: uuid("delivery_zone_id").references(() => deliveryZones.id, { onDelete: "set null" }),
    deliveryZoneName: text("delivery_zone_name"),
    addressText: text("address_text"),
    landmark: text("landmark"),
    lat: doublePrecision("lat"),
    lng: doublePrecision("lng"),
    customerName: text("customer_name"),
    customerPhone: text("customer_phone").notNull(),
    note: text("note"),

    paymentProvider: text("payment_provider"),
    paymentRef: text("payment_ref").unique(),
    paidAt: timestamp("paid_at", { withTimezone: true }),
    deliveredAt: timestamp("delivered_at", { withTimezone: true }),
    confirmedAt: timestamp("confirmed_at", { withTimezone: true }),
    payoutRef: text("payout_ref"),
    paidOutAt: timestamp("paid_out_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("orders_seller_created_idx").on(t.sellerId, t.createdAt),
    index("orders_status_idx").on(t.status),
    index("orders_customer_idx").on(t.customerId),
    check("orders_total_consistent", sql`${t.totalPesewas} = ${t.subtotalPesewas} + ${t.deliveryFeePesewas}`),
    check("orders_amounts_nonneg", sql`${t.subtotalPesewas} > 0 AND ${t.deliveryFeePesewas} >= 0`),
    check(
      "orders_delivery_has_address",
      sql`${t.fulfilment} = 'pickup' OR ${t.addressText} IS NOT NULL OR ${t.lat} IS NOT NULL`,
    ),
  ],
);

export const orderItems = pgTable(
  "order_items",
  {
    id: id(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: uuid("product_id").references(() => products.id, { onDelete: "set null" }),
    variantId: uuid("variant_id").references(() => productVariants.id, { onDelete: "set null" }),
    titleSnapshot: text("title_snapshot").notNull(),
    variantLabel: text("variant_label"),
    unitPricePesewas: money("unit_price_pesewas").notNull(),
    quantity: smallint("quantity").notNull(),
    lineTotalPesewas: money("line_total_pesewas").notNull(),
  },
  (t) => [
    index("order_items_order_idx").on(t.orderId),
    check("order_items_qty_pos", sql`${t.quantity} > 0`),
    check("order_items_line_total", sql`${t.lineTotalPesewas} = ${t.unitPricePesewas} * ${t.quantity}`),
  ],
);

export const orderEvents = pgTable(
  "order_events",
  {
    id: id(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    fromStatus: orderStatus("from_status"),
    toStatus: orderStatus("to_status").notNull(),
    actor: messageSender("actor").notNull(),
    actorAccountId: uuid("actor_account_id").references(() => accounts.id),
    note: text("note"),
    createdAt: createdAt(),
  },
  (t) => [index("order_events_order_idx").on(t.orderId, t.createdAt)],
);

/* ───────────────────────── Conversations ───────────────────────── */

export const conversations = pgTable(
  "conversations",
  {
    id: id(),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "cascade" }),
    customerId: uuid("customer_id")
      .notNull()
      .references(() => customers.id, { onDelete: "cascade" }),
    mode: conversationMode("mode").notNull().default("bot"),
    needsAttention: boolean("needs_attention").notNull().default(false),
    attentionReason: text("attention_reason"),
    lastMessageAt: timestamp("last_message_at", { withTimezone: true }).notNull().defaultNow(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("conversations_seller_customer_uq").on(t.sellerId, t.customerId),
    index("conversations_attention_idx").on(t.needsAttention, t.lastMessageAt),
  ],
);

export const messages = pgTable(
  "messages",
  {
    id: id(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    direction: messageDirection("direction").notNull(),
    sender: messageSender("sender").notNull(),
    body: text("body"),
    /** Meta's message id; unique so webhook retries are idempotent. */
    waMessageId: text("wa_message_id").unique(),
    payload: jsonb("payload"),
    createdAt: createdAt(),
  },
  (t) => [index("messages_conversation_idx").on(t.conversationId, t.createdAt)],
);

/* ───────────────────────── Trust & safety ───────────────────────── */

export const complaints = pgTable(
  "complaints",
  {
    id: id(),
    orderId: uuid("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "restrict" }),
    sellerId: uuid("seller_id")
      .notNull()
      .references(() => sellers.id, { onDelete: "restrict" }),
    customerId: uuid("customer_id")
      .notNull()
      .references(() => customers.id, { onDelete: "restrict" }),
    reason: text("reason").notNull(),
    details: text("details"),
    status: complaintStatus("status").notNull().default("open"),
    resolutionNote: text("resolution_note"),
    resolvedBy: uuid("resolved_by").references(() => accounts.id),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("complaints_status_idx").on(t.status, t.createdAt),
    index("complaints_seller_idx").on(t.sellerId),
  ],
);

/** Phones, Ghana Card numbers (hashed) and MoMo wallets that are banned. */
export const blocklist = pgTable(
  "blocklist",
  {
    id: id(),
    kind: text("kind").notNull(),
    valueHash: text("value_hash").notNull(),
    reason: text("reason"),
    createdBy: uuid("created_by").references(() => accounts.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("blocklist_kind_value_uq").on(t.kind, t.valueHash)],
);

/** Append-only record of admin actions. */
export const auditLog = pgTable(
  "audit_log",
  {
    id: id(),
    actorAccountId: uuid("actor_account_id").references(() => accounts.id),
    action: text("action").notNull(),
    entity: text("entity").notNull(),
    entityId: uuid("entity_id"),
    data: jsonb("data"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_entity_idx").on(t.entity, t.entityId)],
);
